<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref} from 'vue';
import {AlertCircle,ArrowRight,CheckCircle2,Database,FolderOpen,Info,LoaderCircle,RefreshCw,Search,ShieldCheck} from 'lucide-vue-next';
import ApprovalReview from './ApprovalReview.vue';
import ResourceInspector from './ResourceInspector.vue';
import {flowWizardSteps,wizardProgress,wizardReviewState} from '../lib/flow-wizard';
type Item=Record<string,any>;
const props=defineProps<{tenant:string;tenantName:string;projectId?:string|null;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{updated:[];project:[id:string]}>();
const options=ref<Item|null>(null),report=ref<Item|null>(null),fields=ref<Item|null>(null),status=ref<Item|null>(null);
const credential=ref(''),tableKey=ref(''),search=ref(''),fieldSearch=ref(''),name=ref(''),columns=ref<string[]>([]),limited=ref(true),limit=ref(100);
const project=ref(props.projectId??''),busy=ref(''),error=ref(''),statusError=ref(''),uncertainDecision=ref(false),clock=ref(Date.now()),inspection=ref(false);
const errorBox=ref<HTMLElement|null>(null),reviewBox=ref<HTMLElement|null>(null);let alive=true,statusBusy=false,timer:ReturnType<typeof setTimeout>|undefined,clockTimer:ReturnType<typeof setInterval>|undefined,requestId=crypto.randomUUID();
const tables=computed<Item[]>(()=>report.value?.tables??[]);
const table=computed<Item|null>(()=>{try{const [schema,name]=JSON.parse(tableKey.value);return {schema,name};}catch{return null;}});
const visibleFields=computed<Item[]>(()=>fields.value?.table?.columns?.filter((column:Item)=>column.name.toLowerCase().includes(fieldSearch.value.toLowerCase()))??[]);
const steps=computed<Item[]>(()=>status.value?.steps??[]);
const progress=computed(()=>wizardProgress(steps.value,clock.value));
const latest=computed<Item|null>(()=>progress.value.active??steps.value.at(-1)??null);
const historySteps=computed(()=>steps.value.filter(step=>step.id!==latest.value?.id));
const tableResource=computed(()=>status.value?.table?{kind:'table',id:status.value.table.slice(6),ref:status.value.table,name:status.value.project.name}:null);
const loaded=computed(()=>progress.value.completed.has('load_source_table'));
const source=computed(()=>status.value?.creation?.payload?.revision?.flow_wizard?.source);
const result=computed(()=>[...steps.value].reverse().find(step=>step.status==='completed')?.payload?.execution?.result?.flow_wizard);
const reviewPending=computed(()=>latest.value&&wizardReviewState(latest.value,clock.value)==='pending');
const canPrepare=computed(()=>!!name.value.trim()&&!!table.value&&!!fields.value&&!error.value&&columns.value.length>0&&columns.value.length<=200&&(!limited.value||Number.isInteger(limit.value)&&limit.value>=1&&limit.value<=10000));
function key(item:Item){return JSON.stringify([item.schema,item.name]);}
function changed(){requestId=crypto.randomUUID();}
async function fail(reason:unknown){if(!alive)return;error.value=(reason as Error).message||'Não foi possível concluir esta etapa.';await nextTick();errorBox.value?.focus({preventScroll:true});}
async function loadOptions(){busy.value='options';error.value='';try{const data=await props.request(`/catalog/${props.tenant}/flow-wizard/options`);if(alive)options.value=data;}catch(e){await fail(e);}finally{if(alive)busy.value='';}}
async function structure(offset=0){if(busy.value||!credential.value)return;busy.value='structure';error.value='';try{const data=await props.request(`/catalog/${props.tenant}/credentials/${credential.value.slice(11)}/inspect/schema`,'POST',{search:search.value.trim()||null,offset});if(alive){if(!data.verified||!data.search_supported||!data.pagination_supported)throw new Error('O assistente atende PostgreSQL, MySQL e SQL Server. Para este conector, continue a autoria pelo projeto.');report.value=data;tableKey.value='';fields.value=null;columns.value=[];fieldSearch.value='';changed();}}catch(e){report.value=null;tableKey.value='';fields.value=null;columns.value=[];await fail(e);}finally{if(alive)busy.value='';}}
async function chooseCredential(){report.value=null;tableKey.value='';fields.value=null;columns.value=[];search.value='';changed();await structure();}
async function loadFields(offset=0){if(busy.value||!table.value)return;busy.value='fields';error.value='';try{const data=await props.request(`/catalog/${props.tenant}/flow-wizard/fields`,'POST',{credential:credential.value,...{schema:table.value.schema,table:table.value.name},offset});if(alive)fields.value=data;}catch(e){fields.value=null;await fail(e);}finally{if(alive)busy.value='';}}
async function chooseTable(){columns.value=[];fields.value=null;fieldSearch.value='';changed();if(!name.value&&table.value)name.value='Dados de '+table.value.name;await loadFields();}
function selectField(field:string,selected:boolean){columns.value=selected?[...new Set([...columns.value,field])]:columns.value.filter(value=>value!==field);changed();}
function selectPage(){for(const field of visibleFields.value){if(columns.value.length===200)break;if(!columns.value.includes(field.name))columns.value.push(field.name);}changed();}
function schedulePoll(){if(timer)clearTimeout(timer);if(alive&&progress.value.active&&['approved','executing'].includes(progress.value.active.status))timer=setTimeout(()=>refreshStatus(),2500);}
async function refreshStatus(){if(!project.value||statusBusy)return;statusBusy=true;statusError.value='';try{const data=await props.request(`/projects/${project.value}/flow-wizard`);if(alive){const old=latest.value?.status;status.value=data;uncertainDecision.value=false;if(old!==latest.value?.status)emit('updated');}}catch(e){if(alive)statusError.value=(e as Error).message;}finally{statusBusy=false;if(alive&&!statusError.value)schedulePoll();}}
async function prepare(action:string){if(busy.value||progress.value.active)return;busy.value='prepare';error.value='';try{const data=await props.request(`/catalog/${props.tenant}/flow-wizard/actions`,'POST',action==='create_source_flow'?{action,request_id:requestId,name:name.value.trim(),source:{credential:credential.value,schema:table.value?.schema,table:table.value?.name,columns:columns.value,row_limit:limited.value?limit.value:null}}:{action,request_id:requestId,project_id:project.value});if(!alive)return;project.value=data.project.id;await refreshStatus();changed();emit('updated');await nextTick();reviewBox.value?.focus();}catch(e){await fail(e);}finally{if(alive)busy.value='';}}
async function decide(decision:'approved'|'rejected'){if(busy.value||uncertainDecision.value||!reviewPending.value)return;busy.value='decision';error.value='';const review=latest.value;try{await props.request(`/approvals/${review!.id}/decide`,'POST',{decision,fingerprint:review!.fingerprint});if(alive){await refreshStatus();emit('updated');}}catch(e){if(alive){uncertainDecision.value=true;await fail(e);await refreshStatus();}}finally{if(alive)busy.value='';}}
function label(review:Item){return ({pending:'Aguarda sua autorização',approved:'Autorizada · na fila',executing:'Em execução',completed:'Etapa concluída',failed:'Precisa de conferência',expired:'Revisão expirada',rejected:'Solicitação recusada',cancelled:'Solicitação cancelada'} as Item)[wizardReviewState(review,clock.value)]??'Confira o acompanhamento';}
onMounted(()=>{clockTimer=setInterval(()=>clock.value=Date.now(),1000);if(project.value)refreshStatus();else loadOptions();});
onUnmounted(()=>{alive=false;if(timer)clearTimeout(timer);if(clockTimer)clearInterval(clockTimer);});
</script>
<template>
 <section class="flow-wizard" data-tour="flow-wizard" :aria-busy="!!busy">
  <ol class="wizard-steps" aria-label="Etapas da criação do ETL"><li v-for="(step,index) in flowWizardSteps" :key="step.action" :class="{complete:progress.completed.has(step.action),current:(progress.next?.action??progress.active?.payload?.action?.action)===step.action}"><span><CheckCircle2 v-if="progress.completed.has(step.action)" :size="17"/><template v-else>{{index+1}}</template></span><strong>{{step.label}}</strong></li></ol>
  <p v-if="error" ref="errorBox" class="wizard-error" role="alert" tabindex="-1"><AlertCircle :size="17"/>{{error}}</p>
  <p v-if="statusError" class="wizard-error" role="alert"><AlertCircle :size="17"/><span>{{statusError}} <button type="button" class="text-button" @click="refreshStatus">Atualizar acompanhamento</button></span></p>
  <p v-if="busy" class="wizard-note" role="status"><LoaderCircle :size="16" class="spin"/>{{busy==='prepare'?'Conferindo a origem e preparando sua revisão…':busy==='decision'?'Registrando sua decisão…':'Consultando a estrutura disponível…'}}</p>
  <form v-if="!project" class="wizard-form" @submit.prevent="prepare('create_source_flow')">
   <div class="wizard-intro"><Database :size="22"/><div><h3>Transforme uma origem em dados para seus dashboards</h3><p>Escolha uma conexão, a tabela e os campos. O sistema prepara a consulta automaticamente. Você confere e autoriza cada etapa.</p></div></div>
   <label>Conexão de dados<select v-model="credential" :disabled="!!busy" required @change="chooseCredential"><option value="">Escolha a conexão</option><option v-for="item in options?.credentials??[]" :key="item.ref" :value="item.ref">{{item.name}}</option></select></label>
   <p v-if="options&&!options.credentials.length" class="wizard-note">Nenhuma conexão está disponível neste ambiente. Adicione uma conexão de dados pelo catálogo ou confira suas permissões.</p>
   <button v-if="!options&&!busy" type="button" class="secondary-button" @click="loadOptions">Tentar consultar conexões</button>
   <div v-if="credential" class="wizard-search"><label>Buscar tabela ou campo<input v-model="search" maxlength="100" :disabled="!!busy" placeholder="Ex.: financeiro, produtos, unidade…" @keydown.enter.prevent="structure()"></label><button type="button" class="secondary-button" :disabled="!!busy" @click="structure()"><Search :size="15"/>Buscar na fonte</button></div>
   <template v-if="report"><label>Tabela da origem<select v-model="tableKey" required :disabled="!!busy" @change="chooseTable"><option value="">Escolha uma tabela deste resultado</option><option v-for="item in tables" :key="key(item)" :value="key(item)">{{item.schema}} · {{item.name}}</option></select></label><div class="wizard-pages"><span>Resultado {{Math.floor(report.offset/report.page_size)+1}} · consulta de estrutura, sem registros</span><button type="button" class="text-button" :disabled="!!busy||!report.offset" @click="structure(Math.max(0,report.offset-report.page_size))">Anterior</button><button type="button" class="text-button" :disabled="!!busy||report.next_offset==null" @click="structure(report.next_offset)">Próximo</button></div><p v-if="!tables.length" class="wizard-note">Nenhuma tabela ficou visível com esta busca. Tente outro termo ou confira o acesso da conexão.</p></template>
   <div v-if="fields" class="wizard-fields"><div class="wizard-field-heading"><strong>Campos para extrair</strong><span>{{columns.length}} selecionados · até 200</span></div><label class="wizard-field-search">Filtrar campos desta página<input v-model="fieldSearch" placeholder="Buscar um campo…" :disabled="!!busy"></label><div class="wizard-field-tools"><button type="button" class="text-button" :disabled="!!busy||columns.length>=200" @click="selectPage">Selecionar campos visíveis</button><button type="button" class="text-button" :disabled="!!busy||!columns.length" @click="columns=[];changed()">Limpar seleção</button></div><div class="wizard-field-list"><label v-for="column in visibleFields" :key="column.name"><input type="checkbox" :checked="columns.includes(column.name)" :disabled="!!busy||columns.length>=200&&!columns.includes(column.name)" @change="selectField(column.name,($event.target as HTMLInputElement).checked)"><span><strong>{{column.name}}</strong><small>{{column.type}}</small></span></label></div><p class="wizard-note">{{fields.table.columns.length}} de {{fields.table.visible_column_count}} campos visíveis nesta página. A seleção é mantida ao passar para outra página de campos.</p><div v-if="fields.offset||fields.next_offset!=null" class="wizard-pages"><button type="button" class="text-button" :disabled="!!busy||!fields.offset" @click="loadFields(Math.max(0,fields.offset-fields.page_size))">Campos anteriores</button><button type="button" class="text-button" :disabled="!!busy||fields.next_offset==null" @click="loadFields(fields.next_offset)">Próximos campos</button></div></div>
   <template v-if="table"><label>Nome do novo ETL<input v-model="name" maxlength="100" required :disabled="!!busy" @input="changed"></label><div class="wizard-limit"><label><input v-model="limited" type="checkbox" :disabled="!!busy" @change="changed">Começar com uma carga de teste</label><label v-if="limited">Máximo de registros por extração<input v-model.number="limit" type="number" min="1" max="10000" step="1" :disabled="!!busy" @input="changed"></label><p>{{limited?'A tabela conterá uma amostra limitada. Confira a configuração antes de usar seus indicadores como dados completos.':'Sem limite de teste: o agente consultará todos os registros dos campos selecionados nas etapas de extração e carga.'}}</p></div></template>
   <p class="wizard-note"><Info :size="16"/>PostgreSQL, MySQL e SQL Server. Nesta versão, uma tabela de origem e carga total em uma nova tabela privada. Transformações e outras fontes podem ser trabalhadas pelo projeto.</p>
   <button type="submit" class="primary-button" :disabled="!!busy||!canPrepare"><ShieldCheck :size="16"/>Revisar configuração<ArrowRight :size="15"/></button>
  </form>
  <template v-else-if="status"><div class="wizard-summary"><strong>{{status.project.name}}</strong><p>{{source?.name}} · {{source?.schema}}.{{source?.table}}</p><small>{{status.flow||(status.creation?.payload?.flow_wizard_attempt?.started_at?'Criação iniciada · identificador a conferir':'ETL ainda não criado')}}<template v-if="status.table"> · {{status.table}}</template></small><p v-if="source?.row_limit" class="wizard-sample">Carga de teste limitada a {{source.row_limit}} registros por extração.</p></div>
   <article v-if="latest" ref="reviewBox" class="wizard-review" tabindex="-1"><header><ShieldCheck v-if="reviewPending" :size="21"/><LoaderCircle v-else-if="['approved','executing'].includes(latest.status)" :size="21" class="spin"/><CheckCircle2 v-else-if="latest.status==='completed'" :size="21"/><AlertCircle v-else :size="21"/><div><small>{{label(latest)}}</small><h3>{{latest.title}}</h3></div></header><ApprovalReview v-if="reviewPending" :approval="latest" :tenants="[{id:tenant,name:tenantName}]"/><p v-if="latest.payload?.execution?.message" class="wizard-note">{{latest.payload.execution.message}}</p><p v-if="['approved','executing'].includes(latest.status)" class="wizard-note" role="status">Aguarde a confirmação desta etapa. Fechar o assistente não cancela a operação autorizada. Você pode retomar pelo projeto.</p><div v-if="reviewPending" class="wizard-actions"><button type="button" class="secondary-button" :disabled="!!busy||uncertainDecision" @click="decide('rejected')">Recusar</button><button type="button" class="primary-button" :disabled="!!busy||uncertainDecision" @click="decide('approved')">Autorizar esta etapa<ArrowRight :size="15"/></button></div><details v-if="!reviewPending"><summary>Conferir a revisão desta etapa</summary><ApprovalReview :approval="latest" :tenants="[{id:tenant,name:tenantName}]"/></details></article>
   <details v-if="historySteps.length" class="wizard-history"><summary>Conferir etapas anteriores · {{historySteps.length}}</summary><article v-for="step in historySteps" :key="step.id"><h3>{{step.title}} <small>· {{label(step)}}</small></h3><ApprovalReview :approval="step" :tenants="[{id:tenant,name:tenantName}]"/></article></details>
   <p v-if="progress.uncertain" class="wizard-warning">Esta criação já foi iniciada e precisa de conferência. Não solicite uma nova criação antes de verificar o recurso existente pelo projeto; isso evita duplicações.</p>
   <p v-if="result?.message" class="wizard-note">{{result.message}}</p><p v-if="result?.data_check" :class="result.data_check.preview_confirmed?'wizard-success':'wizard-warning'">{{result.data_check.message}}</p>
   <div class="wizard-actions"><button v-if="progress.next" type="button" class="primary-button" :disabled="!!busy||!!statusError" @click="prepare(progress.next.action)">{{progress.next.button}}<ArrowRight :size="15"/></button><button type="button" class="secondary-button" :disabled="!!busy" @click="refreshStatus"><RefreshCw :size="15"/>Atualizar acompanhamento</button><button type="button" class="secondary-button" :disabled="!!busy" @click="emit('project',project)"><FolderOpen :size="15"/>Abrir projeto</button></div>
   <template v-if="loaded&&status.table"><button type="button" class="text-button" @click="inspection=!inspection">{{inspection?'Ocultar conferência':'Conferir a tabela carregada'}}</button><ResourceInspector v-if="inspection&&tableResource" :tenant="tenant" :resource="tableResource" :request="request"/><p class="wizard-note">Confira os registros e os indicadores antes de compartilhar. Publicação e atualização automática precisam ser preparadas pelo projeto, com suas próprias revisões.</p></template>
  </template>
 </section>
</template>
<style scoped>
.flow-wizard{color:#42618a;min-width:0}.wizard-steps{list-style:none;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 24px;padding:0}.wizard-steps li{display:flex;align-items:center;gap:8px;font-size:11px;line-height:1.5;color:#7185a0}.wizard-steps li>span{width:29px;height:29px;flex-shrink:0;display:grid;place-items:center;border:1px solid #dbe6f5;background:#f5f8fc;border-radius:50%}.wizard-steps li.current{color:#1d62be}.wizard-steps li.current>span{background:#eaf2ff;border-color:#9ebef0}.wizard-steps li.complete{color:#2f7959}.wizard-steps li.complete>span{background:#eaf7f0;border-color:#cde7d9}.wizard-intro{display:flex;gap:12px;margin-bottom:20px;background:#f2f7ff;border:1px solid #dbe7f8;padding:16px;border-radius:9px}.wizard-intro>svg{flex-shrink:0;margin-top:2px;color:#3973c2}.wizard-intro h3{font-size:14px;line-height:1.7;margin:0 0 6px}.wizard-intro p{font-size:12px;line-height:1.85;margin:0;color:#617b9d}.wizard-form>label,.wizard-search>label,.wizard-limit>label:not(:first-child){display:block;font-size:12px;color:#3e5e89;margin:16px 0}.wizard-form select,.wizard-form input:not([type=checkbox]){display:block;width:100%;margin-top:7px;min-height:41px;border:1px solid #d8e3f2;border-radius:7px;padding:10px 12px;background:#fff;color:#35577f;font-size:12px}.wizard-form input[type=checkbox]{width:16px;height:16px;flex-shrink:0;accent-color:#1263e9}.wizard-search{display:flex;gap:12px;align-items:flex-end;margin-bottom:14px}.wizard-search>label{flex:1;min-width:0;margin-bottom:0}.wizard-search button{font-size:11px;min-height:41px}.wizard-pages{display:flex;gap:15px;align-items:center;flex-wrap:wrap;font-size:11px;margin:10px 0 16px;color:#6b80a0}.wizard-pages>span{margin-right:auto}.wizard-fields{border:1px solid #dce7f4;border-radius:9px;padding:16px;margin:18px 0}.wizard-field-heading{display:flex;gap:12px;justify-content:space-between;font-size:12px}.wizard-field-heading>span{font-size:11px;color:#637c9e}.wizard-field-search{display:block;font-size:11px;margin-top:14px}.wizard-field-tools{display:flex;gap:16px;flex-wrap:wrap;margin:14px 0}.wizard-field-list{max-height:260px;overflow:auto;overscroll-behavior:contain;border-top:1px solid #e3ecf7}.wizard-field-list>label{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #e3ecf7;cursor:pointer}.wizard-field-list>label>span{display:flex;align-items:center;justify-content:space-between;gap:14px;flex:1;min-width:0}.wizard-field-list strong{font-size:12px;overflow-wrap:anywhere}.wizard-field-list small{font-size:10px;color:#7489a4;text-align:right;overflow-wrap:anywhere}.wizard-limit{background:#fff9ed;border:1px solid #eddfc5;padding:15px;border-radius:8px;margin:18px 0;color:#765a31}.wizard-limit>label:first-child{display:flex;align-items:center;gap:9px;font-size:12px}.wizard-limit input[type=number]{max-width:200px}.wizard-limit p,.wizard-note{font-size:12px;line-height:1.85;color:#627c9f;overflow-wrap:anywhere}.wizard-note{display:flex;align-items:flex-start;gap:8px;margin:14px 0}.wizard-note>svg{flex-shrink:0;margin-top:3px}.wizard-limit p{color:#886b40;margin-bottom:0}.wizard-error,.wizard-warning,.wizard-success{display:flex;gap:9px;align-items:flex-start;font-size:12px;line-height:1.9;padding:13px;border-radius:8px;margin:16px 0;overflow-wrap:anywhere}.wizard-error{color:#a34147;background:#fff2f2;border:1px solid #f0d8da}.wizard-error>svg{flex-shrink:0;margin-top:3px}.wizard-warning{background:#fff9ec;border:1px solid #eedeaf;color:#85632e}.wizard-success{background:#edf8f2;border:1px solid #d1e9dc;color:#2c7152}.wizard-summary{border:1px solid #e0e8f5;background:#f8faff;padding:16px;border-radius:9px;margin-bottom:18px;overflow-wrap:anywhere}.wizard-summary>strong{font-size:14px}.wizard-summary p{font-size:12px;line-height:1.85;margin:7px 0}.wizard-summary small{font-size:11px;color:#7184a1}.wizard-summary .wizard-sample{color:#926a2d}.wizard-review{padding:18px;border:1px solid #b6cdf0;border-radius:10px;box-shadow:0 0 0 3px #f0f5fd;margin-bottom:18px}.wizard-review>header{display:flex;align-items:center;gap:11px;color:#2363be}.wizard-review>header small{font-size:11px}.wizard-review h3{font-size:14px;margin:5px 0}.wizard-history{margin:20px 0}.wizard-history>summary{cursor:pointer;font-size:12px;color:#406b9f}.wizard-history article{border-top:1px solid #e0e9f5;margin-top:16px;padding-top:12px}.wizard-history h3{font-size:12px;line-height:1.85}.wizard-history h3 small{font-size:11px;color:#6c829f}.wizard-review summary{font-size:12px;cursor:pointer;margin:14px 0}.wizard-review:focus-visible,.wizard-error:focus-visible{outline:2px solid #246ce4;outline-offset:4px}.wizard-actions{display:flex;align-items:center;justify-content:flex-end;gap:10px;flex-wrap:wrap;margin:18px 0}.wizard-form>.primary-button{margin-top:5px}.flow-wizard button{font-size:12px}.flow-wizard button:disabled{opacity:.55}.flow-wizard button:focus-visible,.flow-wizard input:focus-visible,.flow-wizard select:focus-visible{outline:2px solid #246ce4;outline-offset:3px}.flow-wizard .text-button{font-size:11px;text-align:left;color:#3066ae}@media(max-width:600px){.wizard-steps{grid-template-columns:1fr 1fr;gap:13px}.wizard-steps li{font-size:10px}.wizard-search{flex-direction:column;align-items:stretch}.wizard-search>label{width:100%}.wizard-search button{align-self:flex-end}.wizard-intro{padding:13px;gap:9px}.wizard-fields{padding:12px}.wizard-field-heading{flex-wrap:wrap}.wizard-field-list>label>span{flex-wrap:wrap;gap:5px}.wizard-review{padding:12px}.wizard-actions{align-items:stretch;flex-direction:column}.wizard-actions>button{justify-content:center}.wizard-pages{gap:12px}.wizard-summary{padding:13px}}
</style>
